CREATE TABLE branch_day_finalization_preparations(organization_id uuid NOT NULL,restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,business_date date NOT NULL,version bigint NOT NULL CHECK(version>0),state jsonb NOT NULL,
 PRIMARY KEY(organization_id,branch_id,business_date),FOREIGN KEY(organization_id,branch_id,business_date) REFERENCES branch_day_approvals(organization_id,branch_id,business_date),CHECK((state->>'version')::bigint=version),CHECK(state->>'status' IN('preparing','prepared','blocked','cancelling','cancelled','expired')));
CREATE TABLE branch_day_finalization_operations(organization_id uuid NOT NULL,operation_id uuid NOT NULL,fingerprint varchar(64) NOT NULL,command jsonb NOT NULL,PRIMARY KEY(organization_id,operation_id));
CREATE TABLE branch_day_finalization_audit(organization_id uuid NOT NULL,branch_id uuid NOT NULL,business_date date NOT NULL,version bigint NOT NULL,action text NOT NULL CHECK(action IN('prepare','cancel','prepare_result','cancel_result','observe')),subject_id varchar(128) NOT NULL,authorization_decision_id uuid NOT NULL,state jsonb NOT NULL,occurred_at_utc timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(organization_id,branch_id,business_date,version));
CREATE FUNCTION protect_finalization_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Finalization preparation history is immutable'; END; $$;
CREATE TRIGGER finalization_operations_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON branch_day_finalization_operations FOR EACH STATEMENT EXECUTE FUNCTION protect_finalization_history();
CREATE TRIGGER finalization_audit_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON branch_day_finalization_audit FOR EACH STATEMENT EXECUTE FUNCTION protect_finalization_history();
